   164  /*  New October 2020
   165      Given true_path_out_buffer (and true_path_bufferlen)
   166      non-zero this finds a dSYM (if such exists) with the
   167      file name in true_path_out_buffer
   168
   169      If not a dSYM it follows debuglink rules to try to find a file
   170      that matches requirements. If found returns DW_DLV_OK and
   171      copies the name to true_path_out_buffer;
   172      If none of the above found, it copies path into true_path
   173      and returns DW_DLV_OK, we know the name is good;
   174
   175      The pathn_fd is owned by libdwarf and is in the created dbg->de_fd
   176      field.
   177  */
   178  int
   179  dwarf_init_path_dl(const char *path,
   180      char            * true_path_out_buffer,
   181      unsigned        true_path_bufferlen,
   182      unsigned        groupnumber,
   183      Dwarf_Handler   errhand,
   184      Dwarf_Ptr       errarg,
   185      Dwarf_Debug     * ret_dbg,
   186      char            ** dl_path_array,
   187      unsigned int    dl_path_count,
   188      unsigned char   * path_source,
   189      Dwarf_Error     * error)
   190  {
   191      unsigned       ftype = 0;
   192      unsigned       endian = 0;
   193      unsigned       offsetsize = 0;
   194      Dwarf_Unsigned filesize = 0;
   195      int res =  DW_DLV_ERROR;
   196      int errcode = 0;
   197      int fd = -1;
   198      Dwarf_Debug dbg = 0;
   199      char *file_path = 0;
   200      unsigned char  lpath_source = DW_PATHSOURCE_basic;
   201
   202      if (!ret_dbg) {
   203          DWARF_DBG_ERROR(NULL,DW_DLE_DWARF_INIT_DBG_NULL,
   204              DW_DLV_ERROR);
   205      }
   206      /*  Non-null *ret_dbg will cause problems dealing with
   207          DW_DLV_ERROR */
   208      *ret_dbg = 0;
   209      if (!path) {
   210          /* Oops. Null path */
   211          _dwarf_error_string(NULL,
   212              error,DW_DLE_STRING_PTR_NULL,
   213              "DW_DLE_STRING_PTR_NULL: Passing a"
   214              " null path argument to "
   215              "dwarf_init_path or dwarf_init_path_dl"
   216              " cannot work. Error.");
   217          return DW_DLV_ERROR;
   218      }
   219      /* a special dsym call so we only check once. */
   220      if (true_path_out_buffer) {
   221          res = dwarf_object_detector_path_dSYM(path,
   222              true_path_out_buffer,
   223              true_path_bufferlen,
   224              dl_path_array,dl_path_count,
   225              &ftype,&endian,&offsetsize,&filesize,
   226              &lpath_source,
   227              &errcode);
   228          if (res != DW_DLV_OK) {
   229              if (res == DW_DLV_ERROR) {
   230                  /* ignore error. Look further. */
   231                  errcode = 0;
   232              }
   233          }
   234      }
   235      if (res != DW_DLV_OK) {
   236          res = dwarf_object_detector_path_b(path,
   237              true_path_out_buffer,
   238              true_path_bufferlen,
   239              dl_path_array,dl_path_count,
   240              &ftype,&endian,&offsetsize,&filesize,
