   835  int
   836  dwarf_object_detector_path_b(
   837      const char  * path,
   838      char *        outpath,
   839      unsigned long outpath_len,
   840      char **       gl_pathnames,
   841      unsigned      gl_pathcount,
   842      unsigned *    ftype,
   843      unsigned *    endian,
   844      unsigned *    offsetsize,
   845      Dwarf_Unsigned * filesize,
   846      unsigned char *  pathsource,
   847      int *errcode)
   848  {
   849      int fd = -1;
   850      int res = 0;
   851      int have_outpath = outpath && outpath_len;
   852      unsigned char lpathsource = DW_PATHSOURCE_basic;
   853
   854      if (pathsource) {
   855          lpathsource = *pathsource;
   856      }
   857      if (lpathsource == DW_PATHSOURCE_basic && have_outpath) {
   858          /*  On return from the following call  we could well
   859              close the fd above and open a new one. */
   860          int debuglink_fd = -1;
   861          unsigned long dllen = 0;
   862          char *cp = 0;
   863          dwarfstring m;
   864
   865          dwarfstring_constructor(&m);
   866          res = _dwarf_debuglink_finder_internal(
   867              gl_pathnames,gl_pathcount,
   868              (char *)path, &m,&debuglink_fd, errcode);
   869          if (res == DW_DLV_ERROR) {
   870              dwarfstring_destructor(&m);
   871              if (debuglink_fd != -1) {
   872                  close(debuglink_fd);
   873              }
   874              return res;
   875          }
